//! The integrator study (#12): its published table matches the code, and its results show
//! what the study claims.

use mjk_sim::validation::integrators::{Method, RUNS, StudyRow, integrator_study, markdown};

/// The table the book includes, generated by `mjk validate integrators`.
const PUBLISHED: &str = include_str!("../../../docs/src/validation/integrator-study.md");

fn rows_for(rows: &[StudyRow], method: Method) -> Vec<StudyRow> {
    rows.iter()
        .filter(|row| row.method == method)
        .copied()
        .collect()
}

#[test]
fn the_published_table_matches_the_code() {
    let rows = integrator_study().expect("the study body is physical");
    assert_eq!(
        markdown(&rows),
        PUBLISHED,
        "regenerate with: cargo run -p mjk-cli -- validate integrators > docs/src/validation/integrator-study.md"
    );
}

#[test]
fn the_study_shows_what_it_claims() {
    let rows = integrator_study().expect("the study body is physical");
    assert_eq!(rows.len(), RUNS.len() * Method::ALL.len());
    for row in rows_for(&rows, Method::Rkmk4) {
        // On the group by construction: rounding only, with no renormalization.
        assert!(row.unit_norm_error < 1e-12, "{row:?}");
    }
    for row in rows_for(&rows, Method::Rk4) {
        assert!(row.unit_norm_error < 1e-15, "{row:?}");
    }
    for row in rows_for(&rows, Method::Rk4Unnormalized) {
        // RK4 alone leaves the sphere, by more at larger steps.
        assert!(row.unit_norm_error > 1e-13, "{row:?}");
    }
    for (row, (dt_s, steps)) in rows_for(&rows, Method::Rkmk4).iter().zip(RUNS) {
        assert_eq!((row.dt_s.to_bits(), row.steps), (dt_s.to_bits(), steps));
        // Fourth order: drifts shrink by far more than the step between runs.
        assert!(
            row.energy_drift < 1e-5 && row.momentum_drift < 1e-4,
            "{row:?}"
        );
    }
}

#[test]
fn methods_name_themselves_and_count_their_work() {
    let expected = [
        (Method::Rk4Unnormalized, "RK4, not renormalized", [4, 0, 0]),
        (Method::Rk4, "RK4, renormalized", [4, 0, 0]),
        (Method::Rkmk4, "RKMK4", [4, 5, 4]),
    ];
    for (method, name, cost) in expected {
        assert_eq!(method.name(), name);
        assert_eq!(method.cost(), cost);
    }
    assert_eq!(
        Method::ALL.map(Method::name),
        expected.map(|(_, name, _)| name)
    );
}

#[test]
fn advancing_matches_the_study_run() {
    let y = Method::Rkmk4
        .advance(0.05, 20)
        .expect("the study body is physical");
    assert!((y.attitude.norm() - 1.0).abs() < 1e-14);
    assert!(y.angular_velocity.norm() > 5.0);
    let y0 = Method::Rk4
        .advance(0.05, 0)
        .expect("the study body is physical");
    assert!((y0.angular_velocity.y - 6.0).abs() < 1e-15);
}
